<?php
namespace ZinCelestial\Platform\Network; defined('ABSPATH')||exit;
final class PolicyController{public function register():void{add_action('network_admin_menu',array($this,'menu'));add_action('admin_post_zcp_save_asset_policy',array($this,'save'));}public function menu():void{add_submenu_page('zcp-network',__('Policy Management','zincelestial-platform'),__('Policies','zincelestial-platform'),'manage_network_options','zcp-policies',array($this,'render'));}public function save():void{if(!current_user_can('manage_network_options'))wp_die(esc_html__('Insufficient permissions.','zincelestial-platform'));check_admin_referer('zcp_save_asset_policy');$raw=(array)wp_unslash($_POST['policy']??array());AssetPolicy::update($raw);wp_safe_redirect(network_admin_url('admin.php?page=zcp-policies&updated=1'));exit;}public function render():void{if(!current_user_can('manage_network_options'))return;$p=AssetPolicy::all();echo '<div class="wrap zcp-admin"><h1>'.esc_html__('Network Policy Management','zincelestial-platform').'</h1><p>'.esc_html__('Network policy takes precedence over site configuration.','zincelestial-platform').'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('zcp_save_asset_policy');echo '<input type="hidden" name="action" value="zcp_save_asset_policy"><table class="form-table"><tr><th>'.esc_html__('Asset policy mode','zincelestial-platform').'</th><td><select name="policy[mode]">';foreach(array('allow_site'=>__('Allow site rules','zincelestial-platform'),'network_only'=>__('Network rules only','zincelestial-platform'),'disabled'=>__('Disable optimization','zincelestial-platform')) as $v=>$label)echo '<option value="'.esc_attr($v).'" '.selected($p['mode'],$v,false).'>'.esc_html($label).'</option>';echo '</select></td></tr><tr><th>'.esc_html__('Locked handles','zincelestial-platform').'</th><td><textarea name="policy[locked_handles_text]" rows="8" class="large-text code">'.esc_textarea(implode("\n",$p['locked_handles'])).'</textarea><p class="description">'.esc_html__('One handle per line. Locked handles cannot be changed by site administrators.','zincelestial-platform').'</p></td></tr></table>';submit_button(__('Save network policy','zincelestial-platform'));echo '</form></div>';}}
